return $input.all().map(item => {
  const data = item.json;

  if (data.telegramId !== undefined) {
    return {
      json: {
        ...data,
        recordType: "user"
      }
    };
  }

  return {
    json: {
      ...data,
      recordType: "event"
    }
  };
});

const items = $input.all().map(item => item.json);

const users = items.filter(item =>
  item.recordType === "user" &&
  item.awaitingPreferences !== true
);
const events = items.filter(item => item.recordType === "event");

const parisToday = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Europe/Paris",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(new Date());

const dayNames = {
  monday: 1, tuesday: 2, wednesday: 3, thursday: 4,
  friday: 5, saturday: 6, sunday: 0,
  lundi: 1, mardi: 2, mercredi: 3, jeudi: 4,
  vendredi: 5, samedi: 6, dimanche: 0
};

function normalize(value) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

function parseDays(value) {
  const text = normalize(value);

  if (!text || /\b(any|tous|toutes|peu importe)\b/.test(text)) {
    return null;
  }

  const found = new Set();

  for (const [name, number] of Object.entries(dayNames)) {
    if (new RegExp(`\\b${name}\\b`, "i").test(text)) {
      found.add(number);
    }
  }

  return found.size ? found : null;
}

function getOccurrences(event) {
  const raw = event.occurrences;

  if (typeof raw === "string" && raw.trim()) {
    return raw.split(";").map(part => {
      const start = part.split("_")[0];
      const date = new Date(start);

      return Number.isNaN(date.getTime()) ? null : date;
    }).filter(Boolean);
  }

  const start = new Date(event.dateStart);

  return Number.isNaN(start.getTime()) ? [] : [start];
}

function priceMatches(user, event) {
  const budget = Number(user.maxPrice);

  if (!Number.isFinite(budget) || budget <= 0) return true;

  const text = normalize(
    `${event.priceType || ""} ${event.priceDetail || ""}`
      .replace(/<[^>]*>/g, " ")
  );

  if (/gratuit|free|entree libre/.test(text)) return true;

  // Détecte les fourchettes comme « de 8 à 20 euros »
  const range = text.match(
    /(?:de\s*)?(\d+(?:[.,]\d{1,2})?)\s*(?:€|euros?)?\s*(?:a|à|[-–])\s*(\d+(?:[.,]\d{1,2})?)\s*(?:€|euros?)?/i
  );

  if (range) {
    const maximum = Number(range[2].replace(",", "."));
    return maximum <= budget;
  }

  const match = text.match(/(\d+(?:[.,]\d{1,2})?)/);

  // Si le tarif est inconnu, ne pas exclure arbitrairement le spectacle.
  if (!match) return true;

  return Number(match[1].replace(",", ".")) <= budget;
}

function genreMatches(user, event) {
  const wanted = normalize(user.genrePreference);
  const actual = normalize(event.genre || event.category);

  if (!wanted || /\b(any|peu importe)\b/.test(wanted)) return true;
  if (!actual) return false;

  const aliases = {
    comedy: ["comedy", "comedie", "humour", "humoristique"],
    comedie: ["comedy", "comedie", "humour", "humoristique"],
    tragedy: ["tragedy", "tragedie"],
    tragedie: ["tragedy", "tragedie"],
    musical: ["musical", "comedie musicale", "comedy musical"],
    contemporary: ["contemporary", "contemporain", "contemporaine"],
    classic: ["classic", "classique"],
    drama: ["drama", "drame"],
    "absurd theatre": [
      "absurd theatre",
      "theatre de l'absurde",
      "absurde"
    ]
  };

  const accepted = aliases[wanted] || [wanted];

  return accepted.some(term =>
    actual.includes(term) || term.includes(actual)
  );
}

function areaMatches(user, event) {
  const wanted = normalize(user.preferredArea);

  if (!wanted || /\b(any|peu importe)\b/.test(wanted)) return true;

  const location = normalize(
    `${event.address || ""} ${event.postcode || ""} ${event.venue || ""}`
  );

  const match = wanted.match(/\b(\d{1,2})(?:er|eme|e|st|nd|rd|th)?\b/);

  if (match) {
    const arrondissement = Number(match[1]);

    if (arrondissement < 1 || arrondissement > 20) return false;

    const postalCode = String(75000 + arrondissement);

    return location.includes(postalCode) ||
      new RegExp(
        `\\b${arrondissement}\\s*(?:e|er|eme|arrondissement)\\b`
      ).test(location);
  }

  return location.includes(wanted);
}

function matches(user, event) {
  const occurrences = getOccurrences(event);

  const futureOccurrences = occurrences.filter(date =>
    date.toLocaleDateString("en-CA", {
      timeZone: "Europe/Paris"
    }) >= parisToday
  );

  if (!futureOccurrences.length) return false;
  if (!genreMatches(user, event)) return false;
  if (!priceMatches(user, event)) return false;
  if (!areaMatches(user, event)) return false;

  const days = parseDays(user.preferredPeriod);

  if (days && !futureOccurrences.some(date => days.has(date.getDay()))) {
    return false;
  }

  return true;
}

const results = [];

for (const user of users) {
  for (const event of events.filter(event => matches(user, event))) {
    const futureDates = getOccurrences(event)
      .filter(date =>
        date.toLocaleDateString("en-CA", {
          timeZone: "Europe/Paris"
        }) >= parisToday
      )
      .sort((a, b) => a - b);

    results.push({
      json: {
        telegramId: user.telegramId,
        genrePreference: user.genrePreference,
        maxPrice: user.maxPrice,
        preferredPeriod: user.preferredPeriod,
        preferredArea: user.preferredArea,
        title: event.title,
        description: event.description,
        genre: event.genre,
        dateStart: futureDates[0]?.toISOString() || event.dateStart,
        dateEnd: event.dateEnd,
        occurrences: event.occurrences,
        priceType: event.priceType,
        priceDetail: event.priceDetail,
        venue: event.venue,
        address: event.address,
        postcode: event.postcode,
        bookingLink: event.bookingLink,
        sourceEventId: event.sourceEventId
      }
    });
  }
}

return results;

const items = $input.all().map(item => item.json);

// Les spectacles candidats possèdent un titre et un identifiant Telegram.
// Les anciennes notifications possèdent un statut.
const candidates = items.filter(item =>
  item.telegramId !== undefined &&
  item.telegramId !== null &&
  item.sourceEventId !== undefined &&
  item.sourceEventId !== null &&
  item.status === undefined
);

const sent = items.filter(item => item.status === "sent");

const alreadySent = new Set(
  sent
    .filter(item =>
      item.telegramId != null &&
      item.sourceEventId != null
    )
    .map(item =>
      `${String(item.telegramId)}::${String(item.sourceEventId)}`
    )
);

return candidates
  .filter(item =>
    !alreadySent.has(
      `${String(item.telegramId)}::${String(item.sourceEventId)}`
    )
  )
  .map(item => ({ json: item }));

const items = $('Regrouper les spectacles').all();

return items.flatMap(item => {
  const data = item.json;

  return (data.notifications || []).map(event => ({
    json: {
      telegramId: data.telegramId,
      sourceEventId: event.sourceEventId,
      sentAt: new Date().toISOString(),
      status: "sent"
    }
  }));
});

const items = $input.all().map(item => item.json);

// Regrouper les spectacles par utilisateur Telegram
const groups = {};

for (const event of items) {
  const id = String(event.telegramId);

  if (!groups[id]) {
    groups[id] = [];
  }

  groups[id].push(event);
}

return Object.entries(groups).map(([telegramId, events]) => {
  const lines = events.map((event, index) => {
    const clean = value =>
      String(value || "")
        .replace(/<[^>]*>/g, " ")
        .replace(/&nbsp;/g, " ")
        .replace(/\s+/g, " ")
        .trim();

    return [
      `${index + 1}. ${clean(event.title) || "Titre à confirmer"}`,
      `Genre : ${clean(event.genre) || "Non précisé"}`,
      `Lieu : ${clean(event.venue) || "À confirmer"}`,
      `Date : ${clean(event.dateStart) || "À confirmer"}`,
      `Prix : ${clean(event.priceDetail || event.priceType) || "À vérifier"}`,
      event.bookingLink
        ? `Réservation : ${event.bookingLink}`
        : "Lien de réservation indisponible"
    ].join("\n");
  });

  return {
    json: {
      telegramId,
      message:
        `TheatreMatch — ${events.length} spectacle(s) for you !\n\n` +
        lines.join("\n\n"),
      notifications: events
    }
  };
});
